(4626051, 665270, 77543, '<td valign="top">I''d have given this a square crop</td>', 'I''d have given this a square crop', '2008-04-09 07:35:13.000000', NULL, 1),
(4626052, 667153, 77543, '<td valign="top">The stem in the top right is drawing me away from the flower</td>', 'The stem in the top right is drawing me away from the flower', '2008-04-09 07:35:48.000000', NULL, 1),
(4626055, 667234, 77543, '<td valign="top">I thing the angle is wrong for this challenge. Either take it square on or at 45 degrees.</td>', 'I thing the angle is wrong for this challenge. Either take it square on or at 45 degrees.', '2008-04-09 07:38:03.000000', NULL, 1),
(4626056, 667166, 77543, '<td valign="top">The overall impression is of a group of flowers that are off centre.</td>', 'The overall impression is of a group of flowers that are off centre.', '2008-04-09 07:38:32.000000', NULL, 1),
(4626058, 666109, 77543, '<td valign="top">Yes this meets the challenge but I don''t think it''s very original.</td>', 'Yes this meets the challenge but I don''t think it''s very original.', '2008-04-09 07:39:45.000000', NULL, 1),
(4626059, 667386, 77543, '<td valign="top">More thought needs to go into the background.</td>', 'More thought needs to go into the background.', '2008-04-09 07:40:02.000000', NULL, 1),
(4626064, 666780, 77543, '<td valign="top">there is a distraction in the top left</td>', 'there is a distraction in the top left', '2008-04-09 07:46:27.000000', NULL, 1),
(4626065, 665805, 77543, '<td valign="top">the background plnt on the right is too bright - it takes the eye away from the main subject.</td>', 'the background plnt on the right is too bright - it takes the eye away from the main subject.', '2008-04-09 07:46:59.000000', NULL, 1),
(4626066, 666403, 77543, '<td valign="top">one leg is cut off</td>', 'one leg is cut off', '2008-04-09 07:47:26.000000', NULL, 1),
(4626068, 665463, 77543, '<td valign="top">I see three flowers that or not centred. If the small flower on the left wasn''t there it would work better.</td>', 'I see three flowers that or not centred. If the small flower on the left wasn''t there it would work better.', '2008-04-09 07:48:23.000000', NULL, 1),
(4626070, 666094, 77543, '<td valign="top">For this challenge I think it would work better straight</td>', 'For this challenge I think it would work better straight', '2008-04-09 07:49:00.000000', NULL, 1),
(4626071, 666696, 77543, '<td valign="top">This is messy</td>', 'This is messy', '2008-04-09 07:49:23.000000', NULL, 1),
(4626073, 665336, 77543, '<td valign="top">The pendent is not in the centre and a hand is not symmetrical so it doesn''t have a centre point.</td>', 'The pendent is not in the centre and a hand is not symmetrical so it doesn''t have a centre point.', '2008-04-09 07:50:33.000000', NULL, 1),
(4626075, 667187, 32011, '<td valign="top">While the stigma is centred and in focus, there''s not enough there to keep the interest long.  The colour is nice and the focus is clear, however I think the image suffers b/c of the shallow DOF and a lack of balance (due to the bottom right section being in focus and best light.</td>', 'While the stigma is centred and in focus, there''s not enough there to keep the interest long.  The colour is nice and the focus is clear, however I think the image suffers b/c of the shallow DOF and a lack of balance (due to the bottom right section being in focus and best light.', '2008-04-09 07:51:27.000000', NULL, 1),
(4626076, 667188, 77543, '<td valign="top">The other flowers in the background are a major distraction</td>', 'The other flowers in the background are a major distraction', '2008-04-09 07:51:27.000000', NULL, 1),
(4626078, 667369, 77543, '<td valign="top">This image would work much better if it wasn''t centred. So it wasn''t a good choice for this challenge.</td>', 'This image would work much better if it wasn''t centred. So it wasn''t a good choice for this challenge.', '2008-04-09 07:52:15.000000', NULL, 1),
(4626082, 667272, 88204, '<td valign="top">Great color, nice capture of motion.</td>', 'Great color, nice capture of motion.', '2008-04-09 07:53:48.000000', NULL, 1),
(4626084, 666771, 32011, '<td valign="top">Nice.  I like the colours and the composition.  There''s a variety in the image thanks to the arrangement of flowers without compromising the theme... clever.  Contrast is great, as is the focus... my only issue with this is the petals at the bottom sticking up and out of the field of focus.  Other than that, love this photo.  Well done.</td>', 'Nice.  I like the colours and the composition.  There''s a variety in the image thanks to the arrangement of flowers without compromising the theme... clever.  Contrast is great, as is the focus... my only issue with this is the petals at the bottom sticking up and out of the field of focus.  Other than that, love this photo.  Well done.', '2008-04-09 07:54:27.000000', NULL, 1),
(4626094, 666937, 88204, '<td valign="top">Backlighting is wonderful with just enough light on the face of the cat. Bud on left is a great point of interest to highlight the lighting. Great shot!</td>', 'Backlighting is wonderful with just enough light on the face of the cat. Bud on left is a great point of interest to highlight the lighting. Great shot!', '2008-04-09 07:58:21.000000', NULL, 1),
(4626096, 666235, 88204, '<td valign="top">Beautiful lighting.</td>', 'Beautiful lighting.', '2008-04-09 07:58:53.000000', NULL, 1),
(4626099, 666975, 88204, '<td valign="top">Great detail and focus.</td>', 'Great detail and focus.', '2008-04-09 07:59:33.000000', NULL, 1),
(4626101, 667365, 32011, '<td valign="top">A very nice image... but I don''t feel that this is a centred composition... the main flower/subject isn''t centred vertically nor horizontally... and as far as the overall image goes, the other flowers don''t offset the main flower enough to bring the composition back to the centre of the frame.  Colour is brilliant and you''ve used the DOF well... just that balance issue which hurts this for this challenge.</td>', 'A very nice image... but I don''t feel that this is a centred composition... the main flower/subject isn''t centred vertically nor horizontally... and as far as the overall image goes, the other flowers don''t offset the main flower enough to bring the composition back to the centre of the frame.  Colour is brilliant and you''ve used the DOF well... just that balance issue which hurts this for this challenge.', '2008-04-09 07:59:36.000000', NULL, 1),
(4626102, 666275, 88204, '<td valign="top">Interesting shot although it doesn''t shout "centered" to me.</td>', 'Interesting shot although it doesn''t shout "centered" to me.', '2008-04-09 08:00:05.000000', NULL, 1),
(4626105, 666457, 88204, '<td valign="top">Lighting is a bit dark and blue. Focus isn''t quite sharp enough on the flower and drops.</td>', 'Lighting is a bit dark and blue. Focus isn''t quite sharp enough on the flower and drops.', '2008-04-09 08:01:11.000000', NULL, 1),
(4626108, 666632, 32011, '<td valign="top">Nice details and use of DOF.  Colour is a little flat though.  With the shallow DOF, some tweaking of the red could have given this image some pop... a 3 dimensional quality.</td>', 'Nice details and use of DOF.  Colour is a little flat though.  With the shallow DOF, some tweaking of the red could have given this image some pop... a 3 dimensional quality.', '2008-04-09 08:02:18.000000', NULL, 1),
(4626122, 667381, 49109, '<td valign="top">way oversharpened</td>', 'way oversharpened', '2008-04-09 08:10:07.000000', NULL, 1),
(4626134, 667176, 49109, '<td valign="top">overall pleasing color and  composition, the OOF flowers add much to the picture. a bit too much drops here and too regularly arranged. the drop in the center makes that spot look blurred. a bit of noise/sharpening artefacts in the background.</td>', 'overall pleasing color and  composition, the OOF flowers add much to the picture. a bit too much drops here and too regularly arranged. the drop in the center makes that spot look blurred. a bit of noise/sharpening artefacts in the background.', '2008-04-09 08:12:42.000000', NULL, 1),
(4626136, 667370, 49109, '<td valign="top">this would have been much more appealing in b/w or sepia</td>', 'this would have been much more appealing in b/w or sepia', '2008-04-09 08:13:31.000000', NULL, 1),
(4626138, 667153, 88718, '<td valign="top">Nice choice of flower. focus just about right.</td>', 'Nice choice of flower. focus just about right.', '2008-04-09 08:15:10.000000', NULL, 1),
(4626142, 665593, 88718, '<td valign="top">A bit more reflected light to the front would have helped make the flower stand out more. Great use of depth of field.</td>', 'A bit more reflected light to the front would have helped make the flower stand out more. Great use of depth of field.', '2008-04-09 08:16:12.000000', NULL, 1),
(4626143, 667365, 49109, '<td valign="top">nicely arranged, yet crop is too tight at bottom and right. less DOF had blurred the flowers in the back  and thus produced a more natural look. border is too bold for my taste</td>', 'nicely arranged, yet crop is too tight at bottom and right. less DOF had blurred the flowers in the back  and thus produced a more natural look. border is too bold for my taste', '2008-04-09 08:16:15.000000', NULL, 1),
(4626145, 665590, 88718, '<td valign="top">The crop should have been horizontal (if possible)</td>', 'The crop should have been horizontal (if possible)', '2008-04-09 08:17:33.000000', NULL, 1),
(4626146, 667136, 49109, '<td valign="top">I can imagine this would do better with a very much tighter crop (and you hadn''t have to mention the toes)</td>', 'I can imagine this would do better with a very much tighter crop (and you hadn''t have to mention the toes)', '2008-04-09 08:17:47.000000', NULL, 1),
(4626148, 667051, 88718, '<td valign="top">Pity there''s no light to see the details of the feathers</td>', 'Pity there''s no light to see the details of the feathers', '2008-04-09 08:18:15.000000', NULL, 1),
(4626153, 667166, 88718, '<td valign="top">Nice composition. More light needed on the "hero" tulip and more out of focus background.</td>', 'Nice composition. More light needed on the "hero" tulip and more out of focus background.', '2008-04-09 08:19:28.000000', NULL, 1),
(4626155, 667043, 88718, '<td valign="top">This is backlit nicely, but some reflective light is needed on the girl''s face</td>', 'This is backlit nicely, but some reflective light is needed on the girl''s face', '2008-04-09 08:21:30.000000', NULL, 1),
(4626156, 667410, 49109, '<td valign="top">overall a bit too pale for "spring colors", why the grey background? good focus and crop. border is irregular.</td>', 'overall a bit too pale for "spring colors", why the grey background? good focus and crop. border is irregular.', '2008-04-09 08:22:24.000000', NULL, 1),
(4626157, 667170, 32011, '<td valign="top">I like this... not sure why though... it''s an ear.  Think it''s because it''s such a simple photo, and it''s done so well.  Having it orientated as it is makes you stop to have a longer look at it... it''s not the usual way of seeing an ear.<br/> <br/>The details are good, as is the lighting... the hair is a bit distracting, though, that said, I think it wouldn''t be as good if the hair was tucked behind the ear.  The bottom left of the image is an issue, as it tends to unbalance the image.<br/> <br/>Well done.</td>', 'I like this... not sure why though... it''s an ear.  Think it''s because it''s such a simple photo, and it''s done so well.  Having it orientated as it is makes you stop to have a longer look at it... it''s not the usual way of seeing an ear. The details are good, as is the lighting... the hair is a bit distracting, though, that said, I think it wouldn''t be as good if the hair was tucked behind the ear.  The bottom left of the image is an issue, as it tends to unbalance the image. Well done.', '2008-04-09 08:22:47.000000', NULL, 1),
(4626159, 666937, 49109, '<td valign="top">very well captured, good focus and nice warm color</td>', 'very well captured, good focus and nice warm color', '2008-04-09 08:23:27.000000', NULL, 1),
(4626166, 666171, 49109, '<td valign="top">where have I seen a similar picture before? well composed, good focus; reds are way oversaturated, whites could be a tad brighter.</td>', 'where have I seen a similar picture before? well composed, good focus; reds are way oversaturated, whites could be a tad brighter.', '2008-04-09 08:28:40.000000', NULL, 1),
(4626171, 667001, 32011, '<td valign="top">Not a bad photo... a little bit of noise, and the colours are tad flat.</td>', 'Not a bad photo... a little bit of noise, and the colours are tad flat.', '2008-04-09 08:32:39.000000', NULL, 1),
(4626193, 667301, 72068, '<td valign="top">So cute!</td>', 'So cute!', '2008-04-09 08:46:01.000000', NULL, 1),
(4626195, 666977, 72068, '<td valign="top">That is a very green tree!</td>', 'That is a very green tree!', '2008-04-09 08:46:23.000000', NULL, 1),
(4626222, 666382, 72068, '<td valign="top">Some really interesting shapes here :D</td>', 'Some really interesting shapes here :D', '2008-04-09 08:56:10.000000', NULL, 1),
(4626241, 666710, 77543, '<td valign="top">Much of the subject is to the left so it''s not that centred.</td>', 'Much of the subject is to the left so it''s not that centred.', '2008-04-09 09:07:02.000000', NULL, 1),
(4626244, 665922, 77543, '<td valign="top">The backlighting around the stem is nice but the area around the flowers looks odd.</td>', 'The backlighting around the stem is nice but the area around the flowers looks odd.', '2008-04-09 09:07:48.000000', NULL, 1),
(4626253, 665993, 77543, '<td valign="top">The subject is well captured in mid air but the background is far too messy.</td>', 'The subject is well captured in mid air but the background is far too messy.', '2008-04-09 09:09:33.000000', NULL, 1),
(4626256, 666429, 77543, '<td valign="top">This subject would work much better in a more traditional composition rather than centred.</td>', 'This subject would work much better in a more traditional composition rather than centred.', '2008-04-09 09:10:54.000000', NULL, 1),
(4626257, 666952, 20577, '<td valign="top">I''ve measured the target and it is not exactly centered, so I must give you a 1! You need to pay more attention to detail in the future if you wish to do well here on DPC. We are perfect here and you, well, are not! I would give you a negative one if I could.</td>', 'I''ve measured the target and it is not exactly centered, so I must give you a 1! You need to pay more attention to detail in the future if you wish to do well here on DPC. We are perfect here and you, well, are not! I would give you a negative one if I could.', '2008-04-09 09:11:06.000000', NULL, 1),
(4626258, 665237, 77543, '<td valign="top">Yes it''s centred, well exposed and sharp but it doesn''t have much "wow" factor.</td>', 'Yes it''s centred, well exposed and sharp but it doesn''t have much "wow" factor.', '2008-04-09 09:11:56.000000', NULL, 1),
(4626259, 667334, 77543, '<td valign="top">The background is far to busy</td>', 'The background is far to busy', '2008-04-09 09:12:18.000000', NULL, 1),
(4626263, 666771, 89431, '<td valign="top">wow, great lighting!</td>', 'wow, great lighting!', '2008-04-09 09:15:50.000000', NULL, 1),
(4626271, 665208, 77543, '<td valign="top">This is a good picture but one of those that would probably work better less centred. ie it doesn''t seem that suited to this particular challenge.</td>', 'This is a good picture but one of those that would probably work better less centred. ie it doesn''t seem that suited to this particular challenge.', '2008-04-09 09:19:21.000000', NULL, 1),
(4626273, 667234, 91857, '<td valign="top">Lots of distortion - a little correction would strengthen an already strong image.</td>', 'Lots of distortion - a little correction would strengthen an already strong image.', '2008-04-09 09:19:27.000000', NULL, 1),
(4626274, 667225, 91857, '<td valign="top">The colours look very flat and corners are vignetted. A saturation boost and stopping your lens down would definitely help.</td>', 'The colours look very flat and corners are vignetted. A saturation boost and stopping your lens down would definitely help.', '2008-04-09 09:20:30.000000', NULL, 1),
(4626275, 667274, 91857, '<td valign="top">Stunningly sharp! Very nice.</td>', 'Stunningly sharp! Very nice.', '2008-04-09 09:20:53.000000', NULL, 1),
(4626276, 667223, 91857, '<td valign="top">Very pleasing and serene image. Obviously not possible for this challenge but would suggest a print of this witht the various poles cloned out would be even better.</td>', 'Very pleasing and serene image. Obviously not possible for this challenge but would suggest a print of this witht the various poles cloned out would be even better.', '2008-04-09 09:22:52.000000', NULL, 1),
(4626286, 667402, 91857, '<td valign="top">Well seen - perhaps try rotating by 90 CCW and next time keep your lens parrallel to the web. At present, except for the centre, the majority of the web is OOF.</td>', 'Well seen - perhaps try rotating by 90 CCW and next time keep your lens parrallel to the web. At present, except for the centre, the majority of the web is OOF.', '2008-04-09 09:28:05.000000', NULL, 1),
(4626291, 667210, 77543, '<td valign="top">Yes it''s centred but I wouldn''t want to hang this picture on my wall.</td>', 'Yes it''s centred but I wouldn''t want to hang this picture on my wall.', '2008-04-09 09:28:52.000000', NULL, 1),
(4626293, 665527, 91857, '<td valign="top">Looks a little underexposed - the snow has come out grey :(</td>', 'Looks a little underexposed - the snow has come out grey :(', '2008-04-09 09:29:30.000000', NULL, 1),
(4626296, 667154, 77543, '<td valign="top">This is a good picture but in terms of this challenge the subject is more than just the central peak. There is a very strong diagonal and foreground that is a main element in this picture.</td>', 'This is a good picture but in terms of this challenge the subject is more than just the central peak. There is a very strong diagonal and foreground that is a main element in this picture.', '2008-04-09 09:30:45.000000', NULL, 1),
(4626302, 666837, 91857, '<td valign="top">Good shot - half a second earlier may have got more of his eyes and face in the shot.</td>', 'Good shot - half a second earlier may have got more of his eyes and face in the shot.', '2008-04-09 09:32:52.000000', NULL, 1),
(4626306, 667370, 77543, '<td valign="top">Nice contrast between the motion of the wheel and the sharpness of the hands. For this challenge I think this would have worked better with an overhead view.</td>', 'Nice contrast between the motion of the wheel and the sharpness of the hands. For this challenge I think this would have worked better with an overhead view.', '2008-04-09 09:34:29.000000', NULL, 1),
(4626311, 666065, 77543, '<td valign="top">The insect isn''t in the centre<br/>:-)</td>', 'The insect isn''t in the centre:-)', '2008-04-09 09:34:56.000000', NULL, 1),
(4626316, 667409, 91857, '<td valign="top">The pose of the girl looks quite uncomfortable. Possibly slightly over-exposed?</td>', 'The pose of the girl looks quite uncomfortable. Possibly slightly over-exposed?', '2008-04-09 09:35:56.000000', NULL, 1),
(4626326, 666048, 77543, '<td valign="top">It''s a pity the horse on the right isn''t sharp</td>', 'It''s a pity the horse on the right isn''t sharp', '2008-04-09 09:39:09.000000', NULL, 1),
(4626330, 667142, 77543, '<td valign="top">The boat is not central in the frame. I''d also have tried a much closer crop to remove the buildings on the right. A nice idea though.</td>', 'The boat is not central in the frame. I''d also have tried a much closer crop to remove the buildings on the right. A nice idea though.', '2008-04-09 09:40:45.000000', NULL, 1),
(4626334, 666078, 91314, '<td valign="top">Out of Focus</td>', 'Out of Focus', '2008-04-09 09:41:07.000000', NULL, 1),
(4626338, 666947, 77543, '<td valign="top">That''s an interesting subject.</td>', 'That''s an interesting subject.', '2008-04-09 09:42:27.000000', NULL, 1),
(4626346, 665770, 91314, '<td valign="top">A bit out of focus</td>', 'A bit out of focus', '2008-04-09 09:45:09.000000', NULL, 1),
(4626355, 666848, 58454, '<td valign="top">Looks like there are two entries with the same model at the exact same location - the pictures are to similar... The picture is nice though.</td>', 'Looks like there are two entries with the same model at the exact same location - the pictures are to similar... The picture is nice though.', '2008-04-09 09:47:23.000000', NULL, 1),
(4626357, 666946, 77543, '<td valign="top">The background is too busy.</td>', 'The background is too busy.', '2008-04-09 09:48:21.000000', NULL, 1),
(4626360, 666239, 77543, '<td valign="top">This is another picture that wasn''t designed to be centred. This would work much better in a more tradition off centre composition.</td>', 'This is another picture that wasn''t designed to be centred. This would work much better in a more tradition off centre composition.', '2008-04-09 09:49:22.000000', NULL, 1),
(4626363, 666047, 3102, '<td valign="top">It''s "you''re" not "your" -- sincerely, the anal retentive grammar person.</td>', 'It''s "you''re" not "your" -- sincerely, the anal retentive grammar person.', '2008-04-09 09:49:51.000000', NULL, 1),
(4626365, 666715, 77543, '<td valign="top">For this challenge I''d like to see just the face rather than the off centre body. A tighter crop would have achieved this.</td>', 'For this challenge I''d like to see just the face rather than the off centre body. A tighter crop would have achieved this.', '2008-04-09 09:50:22.000000', NULL, 1),
(4626370, 666296, 77543, '<td valign="top">This is not centred. I see the subject in a "square" that sits in the top left of the frame. The background forming an "L" in the right and bottom of the frame.</td>', 'This is not centred. I see the subject in a "square" that sits in the top left of the frame. The background forming an "L" in the right and bottom of the frame.', '2008-04-09 09:52:07.000000', NULL, 1),
(4626387, 666886, 77543, '<td valign="top">The distinction between the subject and background is unclear.</td>', 'The distinction between the subject and background is unclear.', '2008-04-09 09:57:10.000000', NULL, 1),
(4626409, 666350, 91716, '<td valign="top">Love it !</td>', 'Love it !', '2008-04-09 10:01:58.000000', NULL, 1),
(4626416, 667313, 91716, '<td valign="top">Beautiful</td>', 'Beautiful', '2008-04-09 10:03:54.000000', NULL, 1),
(4626453, 667246, 61138, '<td valign="top">Great subject. Lovely muted tones and soft colour. 8.</td>', 'Great subject. Lovely muted tones and soft colour. 8.', '2008-04-09 10:18:11.000000', NULL, 1),
(4626458, 666186, 61138, '<td valign="top">Nice subject, colour and light. Maybe just a bit loose. 6.</td>', 'Nice subject, colour and light. Maybe just a bit loose. 6.', '2008-04-09 10:19:06.000000', NULL, 1),
(4626463, 666059, 61138, '<td valign="top">Interesting perspective.</td>', 'Interesting perspective.', '2008-04-09 10:20:00.000000', NULL, 1),
(4626470, 665896, 61138, '<td valign="top">This has some impact. Is the focus on her face a little soft? I know it''s tough to shoot candids sometimes...especially when they know you''re shooting. Black and white is a good choice for this. 7.</td>', 'This has some impact. Is the focus on her face a little soft? I know it''s tough to shoot candids sometimes...especially when they know you''re shooting. Black and white is a good choice for this. 7.', '2008-04-09 10:22:00.000000', NULL, 1),
(4626478, 667178, 33672, '<td valign="top">Nice Twist....:P</td>', 'Nice Twist....:P', '2008-04-09 10:23:22.000000', NULL, 1),
(4626479, 667411, 61138, '<td valign="top">Great use of available light. Nice atmosphere and overall feeling. 6.</td>', 'Great use of available light. Nice atmosphere and overall feeling. 6.', '2008-04-09 10:24:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4626493, 665982, 33672, '<td valign="top">Looks a bit tilted, Very nice framing though.</td>', 'Looks a bit tilted, Very nice framing though.', '2008-04-09 10:30:07.000000', NULL, 1),
(4626506, 667224, 77543, '<td valign="top">It''s not quite straight.</td>', 'It''s not quite straight.', '2008-04-09 10:33:39.000000', NULL, 1),
(4626507, 666441, 77543, '<td valign="top">I''m not seeing a "centred" composition and the hand just adds to that.</td>', 'I''m not seeing a "centred" composition and the hand just adds to that.', '2008-04-09 10:34:27.000000', NULL, 1),
(4626509, 665973, 77543, '<td valign="top">This is the sort of shot that requires the subject to be on the left rather than in the centre so we can see the space he is throwing into.</td>', 'This is the sort of shot that requires the subject to be on the left rather than in the centre so we can see the space he is throwing into.', '2008-04-09 10:35:54.000000', NULL, 1),
(4626515, 666771, 77543, '<td valign="top">It looks a bit dark.</td>', 'It looks a bit dark.', '2008-04-09 10:36:47.000000', NULL, 1),
(4626519, 665982, 77543, '<td valign="top">If the subject is meant to be the monument in the distance then it''s overshadowed by the foreground.</td>', 'If the subject is meant to be the monument in the distance then it''s overshadowed by the foreground.', '2008-04-09 10:37:57.000000', NULL, 1),
(4626523, 665989, 61138, '<td valign="top">Beautifully executed. A magical effect. 9.</td>', 'Beautifully executed. A magical effect. 9.', '2008-04-09 10:39:44.000000', NULL, 1),
