INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4630080, 666957, 83375, '<td valign="top">good perspective.</td>', 'good perspective.', '2008-04-10 12:36:00.000000', NULL, 1),
(4630083, 667237, 83375, '<td valign="top">Hey...what kind of duck is this? I took a shot of one of these guys here in WI too and I know it''s not normally here either...it''s only here for a short time while migrating.</td>', 'Hey...what kind of duck is this? I took a shot of one of these guys here in WI too and I know it''s not normally here either...it''s only here for a short time while migrating.', '2008-04-10 12:38:16.000000', NULL, 1),
(4630085, 667375, 75651, '<td valign="top">Your focus seems a bit soft, and the lighting abit tungsten.  Very nice angle selected to shoot from though and creative idea using the cups.</td>', 'Your focus seems a bit soft, and the lighting abit tungsten.  Very nice angle selected to shoot from though and creative idea using the cups.', '2008-04-10 12:39:38.000000', NULL, 1),
(4630088, 666599, 75651, '<td valign="top">Beautiful silouette with rays making very nice lines to follow through the photo.  Well done.</td>', 'Beautiful silouette with rays making very nice lines to follow through the photo.  Well done.', '2008-04-10 12:40:48.000000', NULL, 1),
(4630089, 666004, 75651, '<td valign="top">very nice photograph.  DOF is very well used to pull my eye right to the center of the composition which is where your subject lies.  Great job 9</td>', 'very nice photograph.  DOF is very well used to pull my eye right to the center of the composition which is where your subject lies.  Great job 9', '2008-04-10 12:41:55.000000', NULL, 1),
(4630093, 666834, 75651, '<td valign="top">Great use of shallow focus.  Nice work.</td>', 'Great use of shallow focus.  Nice work.', '2008-04-10 12:43:30.000000', NULL, 1),
(4630101, 666123, 75651, '<td valign="top">Very intersting choice for this competition.  seems a bit dark though.  I''d actually like to see more of the arms holding the belly.  But nice work.</td>', 'Very intersting choice for this competition.  seems a bit dark though.  I''d actually like to see more of the arms holding the belly.  But nice work.', '2008-04-10 12:47:04.000000', NULL, 1),
(4630108, 665824, 83375, '<td valign="top">I don''t think there''s enough separation between the hawk and the background... a shallower DOF or more contrast would help.</td>', 'I don''t think there''s enough separation between the hawk and the background... a shallower DOF or more contrast would help.', '2008-04-10 12:48:01.000000', NULL, 1),
(4630109, 665747, 75651, '<td valign="top">Good find.  It is centered, but more or less of its body would have worked much better.  either show how the body is held up with the legs or get rid of it just past the base of the neck, just like a person.  Very good shot though.  Crisp focus and good whites.</td>', 'Good find.  It is centered, but more or less of its body would have worked much better.  either show how the body is held up with the legs or get rid of it just past the base of the neck, just like a person.  Very good shot though.  Crisp focus and good whites.', '2008-04-10 12:48:34.000000', NULL, 1),
(4630113, 666428, 75651, '<td valign="top">The shot seems to fill the whole frame and I look at everything in it, not just the center.  It is crisp and clean but would have to deduct a bit for it DNMC.</td>', 'The shot seems to fill the whole frame and I look at everything in it, not just the center.  It is crisp and clean but would have to deduct a bit for it DNMC.', '2008-04-10 12:50:06.000000', NULL, 1),
(4630114, 667363, 75651, '<td valign="top">Wonderful wedding photo. Graceful and beautiful bride.  Nicely taken.</td>', 'Wonderful wedding photo. Graceful and beautiful bride.  Nicely taken.', '2008-04-10 12:50:43.000000', NULL, 1),
(4630116, 666080, 83375, '<td valign="top">Floating heads...need a different color background or shirts.</td>', 'Floating heads...need a different color background or shirts.', '2008-04-10 12:51:19.000000', NULL, 1),
(4630118, 667210, 75651, '<td valign="top">The eye seems a bit out of focus and the lighting does not help its case.  May want to try and pull back a bit to allow the focus to come through.</td>', 'The eye seems a bit out of focus and the lighting does not help its case.  May want to try and pull back a bit to allow the focus to come through.', '2008-04-10 12:51:51.000000', NULL, 1),
(4630122, 667035, 75651, '<td valign="top">This shot is set up wonderfully, but I think the lighting hurt it alot.  Taking this shot straight down from above with lots of the table as a border really would have made this shot centered as well as symmetrically appealing.<br/>Creative and worth reshooting in my mind.</td>', 'This shot is set up wonderfully, but I think the lighting hurt it alot.  Taking this shot straight down from above with lots of the table as a border really would have made this shot centered as well as symmetrically appealing.Creative and worth reshooting in my mind.', '2008-04-10 12:53:44.000000', NULL, 1),
(4630129, 666132, 75651, '<td valign="top">The snow falling down is great, but the focus seems a bit soft.  certainly a good idea though and well centered.</td>', 'The snow falling down is great, but the focus seems a bit soft.  certainly a good idea though and well centered.', '2008-04-10 12:54:51.000000', NULL, 1),
(4630135, 666262, 75651, '<td valign="top">Very nicely done.  The curves of the blade are great and the red "blood" coming down really pulls my eye through the whole photograph while still being centered.  The lighting is wonderfu; and really helps to give texture to the blade.  An easy ten for me. Creative, Unique and well taken.</td>', 'Very nicely done.  The curves of the blade are great and the red "blood" coming down really pulls my eye through the whole photograph while still being centered.  The lighting is wonderfu; and really helps to give texture to the blade.  An easy ten for me. Creative, Unique and well taken.', '2008-04-10 12:56:35.000000', NULL, 1),
(4630140, 667161, 34255, '<td valign="top">Good depth of field, but not the most interesting subject matter.</td>', 'Good depth of field, but not the most interesting subject matter.', '2008-04-10 12:58:45.000000', NULL, 1),
(4630142, 667197, 75651, '<td valign="top">The subject itself seems a bit bland in that I''m Not sure what the photo is saying about it''s subject.  It is a tree, but why am I looking?  Perhaps the canopy was blooming or glistening in the sun.  Look around a bit and really try to tell a story in the photo.  It''s a good start though.</td>', 'The subject itself seems a bit bland in that I''m Not sure what the photo is saying about it''s subject.  It is a tree, but why am I looking?  Perhaps the canopy was blooming or glistening in the sun.  Look around a bit and really try to tell a story in the photo.  It''s a good start though.', '2008-04-10 12:59:09.000000', NULL, 1),
(4630145, 665961, 83375, '<td valign="top">Not a bad idea, the focus just looks off.</td>', 'Not a bad idea, the focus just looks off.', '2008-04-10 13:00:26.000000', NULL, 1),
(4630146, 665479, 75651, '<td valign="top">It is a well focused shot, and lighted well, but the overall composition seems a bit bland.  Missing the WOW factor to really be great!  It is a good start though.</td>', 'It is a well focused shot, and lighted well, but the overall composition seems a bit bland.  Missing the WOW factor to really be great!  It is a good start though.', '2008-04-10 13:00:26.000000', NULL, 1),
(4630152, 666970, 75651, '<td valign="top">Very interseting subject.  the lines pull my eye through and from what I can see- I''d say it is centered for the most part.  nice job.</td>', 'Very interseting subject.  the lines pull my eye through and from what I can see- I''d say it is centered for the most part.  nice job.', '2008-04-10 13:01:17.000000', NULL, 1),
