(4630900, 666827, 75651, '<td valign="top">Wondeful use of shallow DOF.  I loike this shot, the only thing that really distracts my eyes is the background.  Perhaps simply proping up a white or black cloth would help eliminate the background and really pull focus to the subject.  Good job.</td>', 'Wondeful use of shallow DOF.  I loike this shot, the only thing that really distracts my eyes is the background.  Perhaps simply proping up a white or black cloth would help eliminate the background and really pull focus to the subject.  Good job.', '2008-04-10 18:14:46.000000', NULL, 1),
(4630903, 667392, 75651, '<td valign="top">Nice framing.  Seems like a scene from a movie.  Very good quality capture.</td>', 'Nice framing.  Seems like a scene from a movie.  Very good quality capture.', '2008-04-10 18:15:13.000000', NULL, 1),
(4630909, 666730, 75651, '<td valign="top">This is knot a bad photo!  Very sharp focus and crisp with a well centered composition.  nice job. The ONLY thing- is that top right corner.  Noticed it just enought to distract me for a second.  Sometimes that''s all it takes though.  Very good work none-the-less.</td>', 'This is knot a bad photo!  Very sharp focus and crisp with a well centered composition.  nice job. The ONLY thing- is that top right corner.  Noticed it just enought to distract me for a second.  Sometimes that''s all it takes though.  Very good work none-the-less.', '2008-04-10 18:17:01.000000', NULL, 1),
(4630915, 667043, 36382, '<td valign="top">I think she is a bit underexposed.  A bit brighter would have been better IMO, even if some of the light behind her got blown out.  I like the pose.  Works well for this challenge.</td>', 'I think she is a bit underexposed.  A bit brighter would have been better IMO, even if some of the light behind her got blown out.  I like the pose.  Works well for this challenge.', '2008-04-10 18:18:56.000000', NULL, 1),
(4630917, 667224, 75651, '<td valign="top">Very interesting architecture. Ever so slightly off-skew.  Really needs to be centered (head on.  And those extensions of the hair would have been really nice framing to pull back a bit and capture those as well.  Theyare kind of the extensions of the subject and you really want those included.  Definitely a good start to something great.</td>', 'Very interesting architecture. Ever so slightly off-skew.  Really needs to be centered (head on.  And those extensions of the hair would have been really nice framing to pull back a bit and capture those as well.  Theyare kind of the extensions of the subject and you really want those included.  Definitely a good start to something great.', '2008-04-10 18:19:03.000000', NULL, 1),
(4630921, 667409, 75651, '<td valign="top">Awesome perspective.  The angle you cose was really captivating right off the bat.  The lightness kind of throws my eyes around though.  May want to darken her up a bit (this will help the clouds in the sky) and up the saturation very slightly to pop those browns out.  The angle really makes it though.</td>', 'Awesome perspective.  The angle you cose was really captivating right off the bat.  The lightness kind of throws my eyes around though.  May want to darken her up a bit (this will help the clouds in the sky) and up the saturation very slightly to pop those browns out.  The angle really makes it though.', '2008-04-10 18:20:54.000000', NULL, 1),
(4630922, 666383, 36382, '<td valign="top">The flower looks good.  I like the shallow dof.  The lower right corner is a bit busy.</td>', 'The flower looks good.  I like the shallow dof.  The lower right corner is a bit busy.', '2008-04-10 18:21:07.000000', NULL, 1),
(4630924, 666736, 75651, '<td valign="top">Great composition with a superb backdrop.  The focus is just a tad too shallow as it really needs to include the front pedals seeing as how that is really what your subject is.  Incredible eye for photography though. Well done!</td>', 'Great composition with a superb backdrop.  The focus is just a tad too shallow as it really needs to include the front pedals seeing as how that is really what your subject is.  Incredible eye for photography though. Well done!', '2008-04-10 18:22:17.000000', NULL, 1),
(4630925, 667050, 22301, '<td valign="top">this is hilarious, I love the point of view, good luck!</td>', 'this is hilarious, I love the point of view, good luck!', '2008-04-10 18:23:08.000000', NULL, 1),
(4630927, 666975, 75651, '<td valign="top">Sharpness is so crisp- look at those eyelashes.  and your color is great. The only thing I see that is distracting from the subject is the similar color of the background and forehead.  It really makes my eyes slip off the subject and into the lighter part which is the background.  Still a very nice capture and good centering.</td>', 'Sharpness is so crisp- look at those eyelashes.  and your color is great. The only thing I see that is distracting from the subject is the similar color of the background and forehead.  It really makes my eyes slip off the subject and into the lighter part which is the background.  Still a very nice capture and good centering.', '2008-04-10 18:23:53.000000', NULL, 1),
(4630930, 667195, 22301, '<td valign="top">it appears half empty, but I am a pessimist...</td>', 'it appears half empty, but I am a pessimist...', '2008-04-10 18:24:30.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4630932, 666815, 75651, '<td valign="top">Beautiful blurry background really pops that yellow bird out.  Crisp sharp focus too.  Perhaps a tighter crop  to bring the bird closer knockiong out some of that background, IMO. Wonderful capture.  Nice job.</td>', 'Beautiful blurry background really pops that yellow bird out.  Crisp sharp focus too.  Perhaps a tighter crop  to bring the bird closer knockiong out some of that background, IMO. Wonderful capture.  Nice job.', '2008-04-10 18:25:36.000000', NULL, 1),
(4630933, 667246, 22301, '<td valign="top">very nice tones and lighting is done well, I may have backed off the yellow overtone.</td>', 'very nice tones and lighting is done well, I may have backed off the yellow overtone.', '2008-04-10 18:25:42.000000', NULL, 1),
(4630935, 666826, 22301, '<td valign="top">great symmetry, I hope the voter reward you for it.</td>', 'great symmetry, I hope the voter reward you for it.', '2008-04-10 18:26:14.000000', NULL, 1),
(4630937, 667228, 75651, '<td valign="top">Great shot.  So much to look at.  I reall strained to see through that dirty glass to a rather sharp cityscape.  I am glad it is all in focus!!  Superb job and good eye.</td>', 'Great shot.  So much to look at.  I reall strained to see through that dirty glass to a rather sharp cityscape.  I am glad it is all in focus!!  Superb job and good eye.', '2008-04-10 18:26:46.000000', NULL, 1),
(4630940, 667331, 22301, '<td valign="top">really interesting photo, its like an impressionistic painting, I like it alot.</td>', 'really interesting photo, its like an impressionistic painting, I like it alot.', '2008-04-10 18:27:12.000000', NULL, 1),
(4630942, 667313, 22301, '<td valign="top">this will be near the top for sure, very nice tones, good luck!</td>', 'this will be near the top for sure, very nice tones, good luck!', '2008-04-10 18:28:11.000000', NULL, 1),
(4630949, 665490, 22301, '<td valign="top">very cool use of the wide angle lens!</td>', 'very cool use of the wide angle lens!', '2008-04-10 18:29:20.000000', NULL, 1),
(4630953, 667288, 22301, '<td valign="top">I like this, not sure why, it has oddness in all the right places</td>', 'I like this, not sure why, it has oddness in all the right places', '2008-04-10 18:30:09.000000', NULL, 1),
(4630957, 667166, 75651, '<td valign="top">Great DOF.  ALmost perfect shallow focus right off that back tip of the petal.  Nice clean and refreshing photo to look at.  Nicely done.</td>', 'Great DOF.  ALmost perfect shallow focus right off that back tip of the petal.  Nice clean and refreshing photo to look at.  Nicely done.', '2008-04-10 18:30:38.000000', NULL, 1),
(4630960, 667117, 75651, '<td valign="top">GReat angle and focus.  not sure I can agree with the centered composition aspect but a good photo none-the-less.</td>', 'GReat angle and focus.  not sure I can agree with the centered composition aspect but a good photo none-the-less.', '2008-04-10 18:31:21.000000', NULL, 1),
(4630961, 666604, 22301, '<td valign="top">a nice treat to see a different perspective of the bug macro. hope the voters like it too!</td>', 'a nice treat to see a different perspective of the bug macro. hope the voters like it too!', '2008-04-10 18:31:34.000000', NULL, 1),
(4630964, 665831, 22301, '<td valign="top">ha! great find on this quick and fleeting moment. :)</td>', 'ha! great find on this quick and fleeting moment. :)', '2008-04-10 18:32:20.000000', NULL, 1),
(4630967, 666994, 75651, '<td valign="top">Very nice soft photography with very warm colors.  A little too soft on some focusing point but I feel like I''m writing in a soft voice as to not wake the child.  (quietly) very nicely done...</td>', 'Very nice soft photography with very warm colors.  A little too soft on some focusing point but I feel like I''m writing in a soft voice as to not wake the child.  (quietly) very nicely done...', '2008-04-10 18:32:36.000000', NULL, 1),
(4630971, 666404, 77543, '<td valign="top">I think I would have cropped a little closer to remove the blue sky - accentuating the bleakness of the bare tree.</td>', 'I think I would have cropped a little closer to remove the blue sky - accentuating the bleakness of the bare tree.', '2008-04-10 18:33:19.000000', NULL, 1),
(4630972, 667409, 22301, '<td valign="top">shannonlee sighting!</td>', 'shannonlee sighting!', '2008-04-10 18:33:20.000000', NULL, 1),
(4630973, 667009, 75651, '<td valign="top">Awww-  Really want to see the top of that crazy hat and the hands too.  I love little hands so I need to see them badly. I''m sure that was a great and memorable photo shoot as well.  Nicely done.</td>', 'Awww-  Really want to see the top of that crazy hat and the hands too.  I love little hands so I need to see them badly. I''m sure that was a great and memorable photo shoot as well.  Nicely done.', '2008-04-10 18:33:44.000000', NULL, 1),
(4630975, 667114, 22301, '<td valign="top">very cool b&amp;w night shot, the absence of light I thin is what gives it its depth.</td>', 'very cool b&w night shot, the absence of light I thin is what gives it its depth.', '2008-04-10 18:33:58.000000', NULL, 1),
(4630978, 666599, 22301, '<td valign="top">that light is amazing, I think this will ribbon and haven''t even seen all the images yet.</td>', 'that light is amazing, I think this will ribbon and haven''t even seen all the images yet.', '2008-04-10 18:34:46.000000', NULL, 1),
(4630980, 667250, 75651, '<td valign="top">The idtilled lightin is nice.  Very posed shot, doesn''t add much for a story.  The out of focus lines on the side really should be the cropping point if anything.  The muted colors areally don''t grab the eyes as much as I want them too, but with some color and more cropping, you are definitey starting a very nice portraiture.</td>', 'The idtilled lightin is nice.  Very posed shot, doesn''t add much for a story.  The out of focus lines on the side really should be the cropping point if anything.  The muted colors areally don''t grab the eyes as much as I want them too, but with some color and more cropping, you are definitey starting a very nice portraiture.', '2008-04-10 18:35:35.000000', NULL, 1),
(4630981, 667068, 22301, '<td valign="top">cool, I like to see new viewpoints of this London staple.</td>', 'cool, I like to see new viewpoints of this London staple.', '2008-04-10 18:36:02.000000', NULL, 1),
(4630983, 667159, 75651, '<td valign="top">Great pose.  Love that you can put any story to this one.  Awesome aneles and B&amp;W composition od clothing.  Great Shot.</td>', 'Great pose.  Love that you can put any story to this one.  Awesome aneles and B&W composition od clothing.  Great Shot.', '2008-04-10 18:36:26.000000', NULL, 1),
(4630985, 666441, 22301, '<td valign="top">lighting is very well done, hope it does well for you.</td>', 'lighting is very well done, hope it does well for you.', '2008-04-10 18:37:17.000000', NULL, 1),
(4630988, 665411, 22301, '<td valign="top">I like how the notch shows a little more detail to the room. Also the color palette works well together.</td>', 'I like how the notch shows a little more detail to the room. Also the color palette works well together.', '2008-04-10 18:38:10.000000', NULL, 1),
(4630992, 666947, 75651, '<td valign="top">Very nice "How''d they do it" shot.  It is good for a snapshot to show people where youve been.  May want to try to simplify the subject a bit though and crop out alot of the nonessentials.</td>', 'Very nice "How''d they do it" shot.  It is good for a snapshot to show people where youve been.  May want to try to simplify the subject a bit though and crop out alot of the nonessentials.', '2008-04-10 18:38:57.000000', NULL, 1),
(4630993, 667136, 22301, '<td valign="top">:D funny stuff</td>', ':D funny stuff', '2008-04-10 18:39:03.000000', NULL, 1),
(4630998, 667065, 22301, '<td valign="top">great lines and detail, I would think it would be hard to find a nice centered comp for this type of auto shot. great result!</td>', 'great lines and detail, I would think it would be hard to find a nice centered comp for this type of auto shot. great result!', '2008-04-10 18:40:23.000000', NULL, 1),
(4630999, 666882, 22301, '<td valign="top">you are a little off center DNMC!!!!!!!!!! :P<br/>jk, its as if he finally disconnected himself from his shadow.</td>', 'you are a little off center DNMC!!!!!!!!!! :Pjk, its as if he finally disconnected himself from his shadow.', '2008-04-10 18:40:45.000000', NULL, 1),
(4631000, 667281, 75651, '<td valign="top">Beautiful array of balck and white zones here.  The unknowing where the falls end up disturbs me abit, but it''s the textures and grayscales that my eyes are really enjoying.  Nicely done.</td>', 'Beautiful array of balck and white zones here.  The unknowing where the falls end up disturbs me abit, but it''s the textures and grayscales that my eyes are really enjoying.  Nicely done.', '2008-04-10 18:41:29.000000', NULL, 1),
(4631009, 666700, 75651, '<td valign="top">Very simple.  And you took the time to put that sun right at the tip.  (There is a dark spot at the top right third mark you may want to crop out for the future) Very good patience and wondferful warm colors.  I would recommend that you crop it even more so the photograph becomes vertival with the plant- but that is only IMO.</td>', 'Very simple.  And you took the time to put that sun right at the tip.  (There is a dark spot at the top right third mark you may want to crop out for the future) Very good patience and wondferful warm colors.  I would recommend that you crop it even more so the photograph becomes vertival with the plant- but that is only IMO.', '2008-04-10 18:43:37.000000', NULL, 1),
(4631010, 667163, 22301, '<td valign="top">thats cool, light is really interesting too, hope it does well for you.</td>', 'thats cool, light is really interesting too, hope it does well for you.', '2008-04-10 18:43:40.000000', NULL, 1),
(4631011, 667159, 22301, '<td valign="top">some may say the pose is awkward, i really like it.</td>', 'some may say the pose is awkward, i really like it.', '2008-04-10 18:44:26.000000', NULL, 1),
(4631017, 667152, 75651, '<td valign="top">Great subject, just watch that focus.  If you take just one second for anything, make sure it is your focus.  Definitely a good start to something great though.</td>', 'Great subject, just watch that focus.  If you take just one second for anything, make sure it is your focus.  Definitely a good start to something great though.', '2008-04-10 18:45:41.000000', NULL, 1),
(4631025, 666357, 22301, '<td valign="top">I like the lighting and composition, it flows well, I like the rust and red in the window as the only color in the photo.</td>', 'I like the lighting and composition, it flows well, I like the rust and red in the window as the only color in the photo.', '2008-04-10 18:49:54.000000', NULL, 1),
(4631026, 667067, 75651, '<td valign="top">Superb.  Breathtaking.  Glorious... running out of word to describe your photo here.  A few dark spots (almost look like halos from maybe some rain?) on the right side and is really taking my eyes to it.  May want to fix that and take that white pole out from the foreground. You have yourself a very nice photo after that.</td>', 'Superb.  Breathtaking.  Glorious... running out of word to describe your photo here.  A few dark spots (almost look like halos from maybe some rain?) on the right side and is really taking my eyes to it.  May want to fix that and take that white pole out from the foreground. You have yourself a very nice photo after that.', '2008-04-10 18:49:59.000000', NULL, 1),
(4631031, 667162, 75651, '<td valign="top">I like the idea here.  Very creative.  Different textures really makes me examine the photo. I don''t say this often, but this may need a person to help break up the scaling.  Great framing and good colors.</td>', 'I like the idea here.  Very creative.  Different textures really makes me examine the photo. I don''t say this often, but this may need a person to help break up the scaling.  Great framing and good colors.', '2008-04-10 18:51:38.000000', NULL, 1),
(4631032, 667197, 77543, '<td valign="top">If it wasn''t for the nature of this challenge I wouldn''t have said the tree in the middle was the subject.</td>', 'If it wasn''t for the nature of this challenge I wouldn''t have said the tree in the middle was the subject.', '2008-04-10 18:51:48.000000', NULL, 1),
(4631033, 667211, 22301, '<td valign="top">great capture, excellent black and white conversion as well as beautiful tonal range, and great framing. If I made awards this would get one.</td>', 'great capture, excellent black and white conversion as well as beautiful tonal range, and great framing. If I made awards this would get one.', '2008-04-10 18:51:50.000000', NULL, 1),
(4631036, 665738, 77543, '<td valign="top">I think you were on the wrong side of the branch - the bird is facing away from you.</td>', 'I think you were on the wrong side of the branch - the bird is facing away from you.', '2008-04-10 18:52:17.000000', NULL, 1),
(4631038, 666848, 22301, '<td valign="top">lighting pose, everything is great. Only nitpick is that the hat looks a little too small. But I suppose you can''t listen to a Californian on how to wear your hat now can you? :P</td>', 'lighting pose, everything is great. Only nitpick is that the hat looks a little too small. But I suppose you can''t listen to a Californian on how to wear your hat now can you? :P', '2008-04-10 18:53:27.000000', NULL, 1),
(4631039, 666885, 77543, '<td valign="top">It doesn''t feel centred in the frame. I''d have taken this shot from the front of the building.</td>', 'It doesn''t feel centred in the frame. I''d have taken this shot from the front of the building.', '2008-04-10 18:53:31.000000', NULL, 1),
(4631040, 667258, 75651, '<td valign="top">He startled me!!  Awesome falls and the person there gives goos perspective on the shot.  Don''t like the 2/3rds face though. kind of distracting.</td>', 'He startled me!!  Awesome falls and the person there gives goos perspective on the shot.  Don''t like the 2/3rds face though. kind of distracting.', '2008-04-10 18:53:37.000000', NULL, 1),
(4631041, 666186, 91857, '<td valign="top">Bit of a dust spot on the RHS.</td>', 'Bit of a dust spot on the RHS.', '2008-04-10 18:53:53.000000', NULL, 1),
(4631043, 666959, 75651, '<td valign="top">Very interesting subject.  The tree with all of it''s complex branches I think, really take away from her beauty and smoothness.  Although th contrast between the two is nice.  GREAT JOB!!  this photo really makes me think about it!!</td>', 'Very interesting subject.  The tree with all of it''s complex branches I think, really take away from her beauty and smoothness.  Although th contrast between the two is nice.  GREAT JOB!!  this photo really makes me think about it!!', '2008-04-10 18:54:42.000000', NULL, 1),
(4631044, 666167, 22301, '<td valign="top">thats awesome!</td>', 'thats awesome!', '2008-04-10 18:55:09.000000', NULL, 1),
(4631045, 666705, 75651, '<td valign="top">Beautiful lines.  Don''t know if I can truely call this centered but I really dig the composition itself.</td>', 'Beautiful lines.  Don''t know if I can truely call this centered but I really dig the composition itself.', '2008-04-10 18:55:24.000000', NULL, 1),
(4631046, 666937, 77543, '<td valign="top">It lacks contrast and the plant in the foreground seems to be in the way.</td>', 'It lacks contrast and the plant in the foreground seems to be in the way.', '2008-04-10 18:55:41.000000', NULL, 1),
(4631047, 666882, 75651, '<td valign="top">Very photojournalistic shot.  Very crisp and clean throughout the whole photo and the subject is truely centered with a great background to pop them out.  Very nice work on this ''city'' shot.</td>', 'Very photojournalistic shot.  Very crisp and clean throughout the whole photo and the subject is truely centered with a great background to pop them out.  Very nice work on this ''city'' shot.', '2008-04-10 18:56:22.000000', NULL, 1),
(4631049, 667253, 77543, '<td valign="top">I''d have taken this from a lower camera position so camera was at the same level as the frame in the centre.</td>', 'I''d have taken this from a lower camera position so camera was at the same level as the frame in the centre.', '2008-04-10 18:56:50.000000', NULL, 1),
(4631050, 667050, 75651, '<td valign="top">Beautiful.  GReat great shot that I am really enjoying looking at.</td>', 'Beautiful.  GReat great shot that I am really enjoying looking at.', '2008-04-10 18:56:56.000000', NULL, 1),
(4631053, 667266, 75651, '<td valign="top">GReat focus and soft lighting.  The composition is wondeful and simple.  Doesn''t have ''WOW'' but certainly like the photograph as a whole. nice work.</td>', 'GReat focus and soft lighting.  The composition is wondeful and simple.  Doesn''t have ''WOW'' but certainly like the photograph as a whole. nice work.', '2008-04-10 18:57:52.000000', NULL, 1),
(4631057, 666262, 22301, '<td valign="top">very cool studio work, reminds me of <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/31.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/31.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/31.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=5515" rel="nofollow" target="_blank">davenit</a>''s website. its a good thing :)</td>', 'very cool studio work, reminds me of  davenit''s website. its a good thing :)', '2008-04-10 18:58:56.000000', NULL, 1),
(4631061, 666695, 22301, '<td valign="top">I hope you don''t get any "snapshot" comments. I think this is a great! you should frame it and let them see as they grow up. :)</td>', 'I hope you don''t get any "snapshot" comments. I think this is a great! you should frame it and let them see as they grow up. :)', '2008-04-10 19:00:42.000000', NULL, 1),
(4631062, 667339, 75651, '<td valign="top">It''s a really interesting photo with grat tones, but what exactly is the subject?  Is it that joint where the leaves come together?  WOuld look wonderful framed, but rather unitriguing.  A ladybug, or droplet of water.  Why focus on that point right there? this only IMO.  I think technically, you have photography nailed!!  Let the photo tell a great story though.</td>', 'It''s a really interesting photo with grat tones, but what exactly is the subject?  Is it that joint where the leaves come together?  WOuld look wonderful framed, but rather unitriguing.  A ladybug, or droplet of water.  Why focus on that point right there? this only IMO.  I think technically, you have photography nailed!!  Let the photo tell a great story though.', '2008-04-10 19:01:22.000000', NULL, 1),
(4631066, 667253, 75651, '<td valign="top">The composition is very nice but the lighting really flattens out the photo.  If taken again at an early or late time of day, those paint peels would look so surreal!!  I think it''s worth reshooting just to find out!</td>', 'The composition is very nice but the lighting really flattens out the photo.  If taken again at an early or late time of day, those paint peels would look so surreal!!  I think it''s worth reshooting just to find out!', '2008-04-10 19:02:21.000000', NULL, 1),
(4631068, 666960, 77543, '<td valign="top">The curved railing is nice. I don''t see a central subject here. Although the sun is on the centre line it is too blown out to really be the subject. The couple of people are not in the centre. In the centre of the picture is a tiny reflection on the sea which is not that prominent and not what I''d call the subject in this picture.</td>', 'The curved railing is nice. I don''t see a central subject here. Although the sun is on the centre line it is too blown out to really be the subject. The couple of people are not in the centre. In the centre of the picture is a tiny reflection on the sea which is not that prominent and not what I''d call the subject in this picture.', '2008-04-10 19:02:55.000000', NULL, 1),
(4631071, 667349, 75651, '<td valign="top">Great photo concept.  The saturation and the lighting are kind of washing the texture of the pedals out a bit.  Very nicely thought out though.</td>', 'Great photo concept.  The saturation and the lighting are kind of washing the texture of the pedals out a bit.  Very nicely thought out though.', '2008-04-10 19:03:29.000000', NULL, 1),
(4631077, 667370, 75651, '<td valign="top">Closer.  Get down and dirty with the clay!  I like the idea for centering, you took it out of what everyone would interpret it as and gave it another meaning while still obiding by the challenge to center you subject.  The lighting is rather tungstenish.  but very nice creativity.</td>', 'Closer.  Get down and dirty with the clay!  I like the idea for centering, you took it out of what everyone would interpret it as and gave it another meaning while still obiding by the challenge to center you subject.  The lighting is rather tungstenish.  but very nice creativity.', '2008-04-10 19:05:28.000000', NULL, 1),
(4631079, 667154, 75651, '<td valign="top">Nice landscape.  Good zones of black and white. This would look rather nice framed.</td>', 'Nice landscape.  Good zones of black and white. This would look rather nice framed.', '2008-04-10 19:06:20.000000', NULL, 1),
(4631081, 667051, 77543, '<td valign="top">This is an excellent capture of a flying bird and the twigs make it extra special. Unfortunately I think this picture would work better in another challenge where you could crop it to give more space in front of the bird than behind.</td>', 'This is an excellent capture of a flying bird and the twigs make it extra special. Unfortunately I think this picture would work better in another challenge where you could crop it to give more space in front of the bird than behind.', '2008-04-10 19:07:27.000000', NULL, 1),
