(4632916, 665770, 81530, '<td valign="top">A little out of focus</td>', 'A little out of focus', '2008-04-11 12:33:41.000000', NULL, 1),
(4632917, 666730, 77543, '<td valign="top">This has a nice abstract quality to it.</td>', 'This has a nice abstract quality to it.', '2008-04-11 12:33:41.000000', NULL, 1),
