(4634583, 667340, 59415, '<td valign="top">That little light reflection on the lower eye lash is a little bit distracting.</td>', 'That little light reflection on the lower eye lash is a little bit distracting.', '2008-04-12 03:34:35.000000', NULL, 1),
(4634584, 666960, 59415, '<td valign="top">This is very well composed.</td>', 'This is very well composed.', '2008-04-12 03:34:51.000000', NULL, 1),
