(4634590, 666905, 59415, '<td valign="top">It is almost that season around here.  I can''t wait!  Very good center composition.</td>', 'It is almost that season around here.  I can''t wait!  Very good center composition.', '2008-04-12 03:37:38.000000', NULL, 1),
(4634592, 667257, 59415, '<td valign="top">That does look good.  Cool flame job.</td>', 'That does look good.  Cool flame job.', '2008-04-12 03:38:22.000000', NULL, 1),
(4634594, 667250, 59415, '<td valign="top">It looks like she is trapped on a space ship.   Maybe the battle star galactica.</td>', 'It looks like she is trapped on a space ship.   Maybe the battle star galactica.', '2008-04-12 03:38:58.000000', NULL, 1),
(4634595, 666460, 59415, '<td valign="top">It is nice to see the nature again.</td>', 'It is nice to see the nature again.', '2008-04-12 03:39:33.000000', NULL, 1),
