(4634599, 667278, 70514, '<td valign="top">Love the flowing water against the rocks and tree.  Nice contrast and processing.</td>', 'Love the flowing water against the rocks and tree.  Nice contrast and processing.', '2008-04-12 03:41:06.000000', NULL, 1),
(4634600, 666015, 59415, '<td valign="top">This is a very nice centered composition.</td>', 'This is a very nice centered composition.', '2008-04-12 03:41:27.000000', NULL, 1),
