INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4634610, 665983, 70514, '<td valign="top">It''s amazing sometimes what thoughts and emotions can be conjured up by a single image.  This is wonderful.  Bonus points for not having a pristine ball in here.</td>', 'It''s amazing sometimes what thoughts and emotions can be conjured up by a single image.  This is wonderful.  Bonus points for not having a pristine ball in here.', '2008-04-12 03:49:36.000000', NULL, 1),
(4634611, 666881, 70514, '<td valign="top">This is one tradition in baseball I''d love to see go away, but I''m fully aware that this is just me.  The lighting and perspective is great.</td>', 'This is one tradition in baseball I''d love to see go away, but I''m fully aware that this is just me.  The lighting and perspective is great.', '2008-04-12 03:50:26.000000', NULL, 1),
(4634612, 667288, 70514, '<td valign="top">Subtle and interesting.</td>', 'Subtle and interesting.', '2008-04-12 03:50:51.000000', NULL, 1),
(4634613, 667046, 70514, '<td valign="top">Sooooo pretty and calming.  Love the colors.</td>', 'Sooooo pretty and calming.  Love the colors.', '2008-04-12 03:51:22.000000', NULL, 1),
(4634614, 666030, 70514, '<td valign="top">Very eerie.  Reminds me of an old prison room.  Wonderful texture maintained with the processing.</td>', 'Very eerie.  Reminds me of an old prison room.  Wonderful texture maintained with the processing.', '2008-04-12 03:52:36.000000', NULL, 1),
(4634615, 667176, 88718, '<td valign="top">This is a lovely exposed shot. Sharpness is perfect. background is also very complementary. Well done</td>', 'This is a lovely exposed shot. Sharpness is perfect. background is also very complementary. Well done', '2008-04-12 03:52:40.000000', NULL, 1),
(4634617, 667228, 70514, '<td valign="top">There is something quite sad about this, and I don''t know why.  Just the emotion I felt when I saw it, I guess.  Very lovely and interesting.</td>', 'There is something quite sad about this, and I don''t know why.  Just the emotion I felt when I saw it, I guess.  Very lovely and interesting.', '2008-04-12 03:53:45.000000', NULL, 1),
(4634619, 667149, 88718, '<td valign="top">Great angle for this shot and lighting is very strong point too. The background could have been a little less sharp.</td>', 'Great angle for this shot and lighting is very strong point too. The background could have been a little less sharp.', '2008-04-12 03:55:34.000000', NULL, 1),
(4634620, 666235, 88718, '<td valign="top">This is striking. I like the use of black background and lighting from side-rear</td>', 'This is striking. I like the use of black background and lighting from side-rear', '2008-04-12 03:57:39.000000', NULL, 1),
(4634621, 667405, 33672, '<td valign="top">Really nice work. Your photo takes the ordinary and makes it extraordinary. The comp and shadows are great.</td>', 'Really nice work. Your photo takes the ordinary and makes it extraordinary. The comp and shadows are great.', '2008-04-12 04:04:45.000000', NULL, 1),
(4634622, 666815, 33672, '<td valign="top">Surreal Bokeh.</td>', 'Surreal Bokeh.', '2008-04-12 04:04:51.000000', NULL, 1),
(4634623, 667333, 33672, '<td valign="top">Incredible sky. Interesting photo.</td>', 'Incredible sky. Interesting photo.', '2008-04-12 04:04:57.000000', NULL, 1),
(4634624, 666441, 33672, '<td valign="top">Beautiful model. Interesting pose.</td>', 'Beautiful model. Interesting pose.', '2008-04-12 04:05:00.000000', NULL, 1),
(4634626, 667195, 89940, '<td valign="top">I really like the lighting on this, it makes the cup look bottomless. The red color realy works well and while I''m not a fan of frames I think it also works well with this photo. Well done.</td>', 'I really like the lighting on this, it makes the cup look bottomless. The red color realy works well and while I''m not a fan of frames I think it also works well with this photo. Well done.', '2008-04-12 04:10:01.000000', NULL, 1),
(4634646, 667370, 91360, '<td valign="top">great!<br/>dont forget to wash your hands later on...8!</td>', 'great!dont forget to wash your hands later on...8!', '2008-04-12 04:29:35.000000', NULL, 1),
(4634649, 666019, 91360, '<td valign="top">funny</td>', 'funny', '2008-04-12 04:30:24.000000', NULL, 1),
(4634654, 667234, 91360, '<td valign="top">nice photoshop editing, love the colors.</td>', 'nice photoshop editing, love the colors.', '2008-04-12 04:32:03.000000', NULL, 1),
(4634660, 667235, 91360, '<td valign="top">scarry...</td>', 'scarry...', '2008-04-12 04:34:25.000000', NULL, 1),
(4634662, 666604, 91360, '<td valign="top">wow</td>', 'wow', '2008-04-12 04:36:37.000000', NULL, 1),
(4634664, 666440, 91360, '<td valign="top">nice reflection</td>', 'nice reflection', '2008-04-12 04:41:14.000000', NULL, 1),
(4634667, 666905, 91360, '<td valign="top">its a fish under?</td>', 'its a fish under?', '2008-04-12 04:43:38.000000', NULL, 1),
(4634680, 666275, 88718, '<td valign="top">Full of action. Pity the crop had to be so tight to llose the back wheel. otherwise great</td>', 'Full of action. Pity the crop had to be so tight to llose the back wheel. otherwise great', '2008-04-12 05:12:46.000000', NULL, 1),
(4634681, 666636, 88718, '<td valign="top">This is a very stark image. perhaps the apple could have been a little larger in the frame and the background appears to be uneven in lighting on the left. Did it taste OK afterwards?</td>', 'This is a very stark image. perhaps the apple could have been a little larger in the frame and the background appears to be uneven in lighting on the left. Did it taste OK afterwards?', '2008-04-12 05:14:36.000000', NULL, 1),
(4634682, 667197, 88718, '<td valign="top">Almost impressionistic. Nice</td>', 'Almost impressionistic. Nice', '2008-04-12 05:15:43.000000', NULL, 1),
(4634683, 666813, 88718, '<td valign="top">This is very harsh lighting which doesn''t give the round form of the ball a chance to show how beautiful it is. I am guessing an on or near-camera flash was used.</td>', 'This is very harsh lighting which doesn''t give the round form of the ball a chance to show how beautiful it is. I am guessing an on or near-camera flash was used.', '2008-04-12 05:17:59.000000', NULL, 1),
(4634684, 666694, 88718, '<td valign="top">This has great atmosphere. makes you want to see what''s around the corner. The exposure is also good. It picks the edges of the stair treads and the iron work to the left.</td>', 'This has great atmosphere. makes you want to see what''s around the corner. The exposure is also good. It picks the edges of the stair treads and the iron work to the left.', '2008-04-12 05:20:07.000000', NULL, 1),
(4634698, 667046, 92480, '<td valign="top">nicely Balanced :)</td>', 'nicely Balanced :)', '2008-04-12 06:16:18.000000', NULL, 1),
(4634714, 665993, 70514, '<td valign="top">Great stop motion!</td>', 'Great stop motion!', '2008-04-12 06:54:54.000000', NULL, 1),
(4634717, 665758, 70514, '<td valign="top">I love the angle and water droplets most.  The colors are so pleasing as well.  Very pretty.</td>', 'I love the angle and water droplets most.  The colors are so pleasing as well.  Very pretty.', '2008-04-12 06:56:47.000000', NULL, 1),
(4634718, 666694, 70514, '<td valign="top">The grain works very nicely here.  Love the bits of light along the stair rail.</td>', 'The grain works very nicely here.  Love the bits of light along the stair rail.', '2008-04-12 06:57:57.000000', NULL, 1),
(4634721, 667208, 70514, '<td valign="top">Interesting and different.  I like the softness of the colors exemplified with the way you took this.</td>', 'Interesting and different.  I like the softness of the colors exemplified with the way you took this.', '2008-04-12 07:00:16.000000', NULL, 1),
(4634723, 665838, 70514, '<td valign="top">I think with a different angle and some processing, this could be more interesting.  I like the idea behind this.  Quite nostalgic.</td>', 'I think with a different angle and some processing, this could be more interesting.  I like the idea behind this.  Quite nostalgic.', '2008-04-12 07:02:45.000000', NULL, 1),
(4634724, 667153, 70514, '<td valign="top">Beautiful with the grass.</td>', 'Beautiful with the grass.', '2008-04-12 07:10:37.000000', NULL, 1),
(4634725, 667313, 70514, '<td valign="top">Mmmmm... beautiful.</td>', 'Mmmmm... beautiful.', '2008-04-12 07:13:10.000000', NULL, 1),
(4634726, 665633, 18450, '<td valign="top">Superb!!!</td>', 'Superb!!!', '2008-04-12 07:14:33.000000', NULL, 1),
(4634727, 666774, 18450, '<td valign="top">Wonderful work!</td>', 'Wonderful work!', '2008-04-12 07:22:36.000000', NULL, 1),
(4634777, 666709, 88083, '<td valign="top">Great portrait!</td>', 'Great portrait!', '2008-04-12 08:57:47.000000', NULL, 1),
(4634852, 666937, 70270, '<td valign="top">Great lighting really puts the focus on the center here</td>', 'Great lighting really puts the focus on the center here', '2008-04-12 10:35:18.000000', NULL, 1),
(4634867, 667176, 70270, '<td valign="top">Great sharpness and tones, wonderful bokeh.  There are too many drops for me as they distract my attention, and detract from the image</td>', 'Great sharpness and tones, wonderful bokeh.  There are too many drops for me as they distract my attention, and detract from the image', '2008-04-12 10:47:34.000000', NULL, 1),
(4634871, 665225, 70270, '<td valign="top">Subtle zoom blur?  Works to great effect here to drill down into your main subject, where your moment of capture is perfect.  10 right out of the box for me.</td>', 'Subtle zoom blur?  Works to great effect here to drill down into your main subject, where your moment of capture is perfect.  10 right out of the box for me.', '2008-04-12 10:52:21.000000', NULL, 1),
(4634879, 667146, 70270, '<td valign="top">Wonderful clouds and nice conversion lends drama to the image.</td>', 'Wonderful clouds and nice conversion lends drama to the image.', '2008-04-12 10:55:47.000000', NULL, 1),
(4634897, 667058, 70270, '<td valign="top">Pier 14!  Looks like an early morning shot.  Nice comp, and love the tones in the sky; one or two people walking down the pier in the foreground would add a bit more interest to the shot, but still nice as is.</td>', 'Pier 14!  Looks like an early morning shot.  Nice comp, and love the tones in the sky; one or two people walking down the pier in the foreground would add a bit more interest to the shot, but still nice as is.', '2008-04-12 11:02:10.000000', NULL, 1),
(4634904, 666827, 19799, '<td valign="top">I like this idea. The out of focus areas creates nice converging lines to the middle objects. Could be my monitor but the black piece appears a bit OOF.</td>', 'I like this idea. The out of focus areas creates nice converging lines to the middle objects. Could be my monitor but the black piece appears a bit OOF.', '2008-04-12 11:06:16.000000', NULL, 1),
(4634908, 666285, 19799, '<td valign="top">This works well! Seems a bit underexposed but it''s nice and sharp.</td>', 'This works well! Seems a bit underexposed but it''s nice and sharp.', '2008-04-12 11:07:30.000000', NULL, 1),
(4634909, 667365, 19799, '<td valign="top">I love the colours in this shot. The yellow-orange really pops.</td>', 'I love the colours in this shot. The yellow-orange really pops.', '2008-04-12 11:08:07.000000', NULL, 1),
(4634910, 667211, 19799, '<td valign="top">This a great creative capture. The only thing I see is I would clone out the leg in the scene so only the shadow is present.</td>', 'This a great creative capture. The only thing I see is I would clone out the leg in the scene so only the shadow is present.', '2008-04-12 11:09:21.000000', NULL, 1),
(4634912, 667234, 19799, '<td valign="top">This works well. The colours really enhance this shot.</td>', 'This works well. The colours really enhance this shot.', '2008-04-12 11:09:49.000000', NULL, 1),
(4634914, 665822, 19799, '<td valign="top">The only thing about this shot, at least for me, is I would like to see the image in the window in focus and the area around it OOF. This is still a nice capture though.</td>', 'The only thing about this shot, at least for me, is I would like to see the image in the window in focus and the area around it OOF. This is still a nice capture though.', '2008-04-12 11:11:22.000000', NULL, 1),
(4634915, 666815, 19799, '<td valign="top">Great capture sticking to the rules of the competition. I think there is too much dead space.</td>', 'Great capture sticking to the rules of the competition. I think there is too much dead space.', '2008-04-12 11:12:29.000000', NULL, 1),
(4634916, 666302, 19799, '<td valign="top">Would have been more interesting with a larger dof.</td>', 'Would have been more interesting with a larger dof.', '2008-04-12 11:13:21.000000', NULL, 1),
(4634918, 667071, 19799, '<td valign="top">Nothing seems to be in focus. Being an indoor pool, this would have been a hard shot to capture with the limited light source.</td>', 'Nothing seems to be in focus. Being an indoor pool, this would have been a hard shot to capture with the limited light source.', '2008-04-12 11:14:51.000000', NULL, 1),
(4634920, 667313, 19799, '<td valign="top">The colouration of this shot is as captivating as the shot itself. Nice work.</td>', 'The colouration of this shot is as captivating as the shot itself. Nice work.', '2008-04-12 11:16:21.000000', NULL, 1),
(4634921, 666132, 19799, '<td valign="top">This centered composition is a nice way to capture this shot in landscape orientation.</td>', 'This centered composition is a nice way to capture this shot in landscape orientation.', '2008-04-12 11:17:09.000000', NULL, 1),
(4634923, 667146, 19799, '<td valign="top">This shot would make a nice background for something.</td>', 'This shot would make a nice background for something.', '2008-04-12 11:17:45.000000', NULL, 1),
(4634925, 666396, 19799, '<td valign="top">I love the background and narrow dof. It definitely follows the theme.</td>', 'I love the background and narrow dof. It definitely follows the theme.', '2008-04-12 11:18:55.000000', NULL, 1),
(4634930, 667068, 19799, '<td valign="top">This shot has a lot going on in it but the centered composition seems to be the perfect way to do it for this shot. The converging lines to the middle of the frame really enhance the shot.</td>', 'This shot has a lot going on in it but the centered composition seems to be the perfect way to do it for this shot. The converging lines to the middle of the frame really enhance the shot.', '2008-04-12 11:20:34.000000', NULL, 1),
