(4636276, 666642, 75651, '<td valign="top">very nice shallow DOF. Saturation may have been a bit much but overall nice photo.</td>', 'very nice shallow DOF. Saturation may have been a bit much but overall nice photo.', '2008-04-13 11:20:55.000000', NULL, 1),
(4636278, 666509, 75651, '<td valign="top">Good composition and sharp focus.</td>', 'Good composition and sharp focus.', '2008-04-13 11:21:45.000000', NULL, 1),
(4636279, 665490, 75651, '<td valign="top">Interesting idea.  The focus on your left hand has a quick falloff and perhaps a tighter crop onto the hands giving a more trapped feeling.  Very nice and creative idea though.  Love the positioning of the hands.</td>', 'Interesting idea.  The focus on your left hand has a quick falloff and perhaps a tighter crop onto the hands giving a more trapped feeling.  Very nice and creative idea though.  Love the positioning of the hands.', '2008-04-13 11:23:23.000000', NULL, 1);
