(4638935, 666723, 59415, '<td valign="top">What a beautiful location to shoot in.  I bet you had a wonderful time in an area like that one.</td>', 'What a beautiful location to shoot in.  I bet you had a wonderful time in an area like that one.', '2008-04-14 16:09:41.000000', NULL, 1),
(4638936, 667346, 59415, '<td valign="top">I love the excellent color and the soft natural light.</td>', 'I love the excellent color and the soft natural light.', '2008-04-14 16:09:57.000000', NULL, 1),
