(4638939, 666044, 59415, '<td valign="top">I wish I looked that buff when I sit on a rock and think.  I am like a scrawny version of the thinker.</td>', 'I wish I looked that buff when I sit on a rock and think.  I am like a scrawny version of the thinker.', '2008-04-14 16:11:12.000000', NULL, 1),
(4638941, 666536, 59415, '<td valign="top">Holy Crap.  At least he doesn''t have to move the entire time he is posing.  However people might have to hold their noses or light a match.</td>', 'Holy Crap.  At least he doesn''t have to move the entire time he is posing.  However people might have to hold their noses or light a match.', '2008-04-14 16:11:59.000000', NULL, 1),
(4638951, 666827, 5364, '<td valign="top">Would it have worked better with the white knight surrounded by the black pieces? You also needed to do something about the background because it gives the impression this is just a snapshot, rather than a considered composition which you were obviously aiming for.</td>', 'Would it have worked better with the white knight surrounded by the black pieces? You also needed to do something about the background because it gives the impression this is just a snapshot, rather than a considered composition which you were obviously aiming for.', '2008-04-14 16:15:49.000000', NULL, 1),
