(4638953, 667258, 59415, '<td valign="top">I hope you didn''t fall in, because that looks like a long ways down!</td>', 'I hope you didn''t fall in, because that looks like a long ways down!', '2008-04-14 16:16:52.000000', NULL, 1),
(4638956, 667252, 59415, '<td valign="top">Very beautiful colors.</td>', 'Very beautiful colors.', '2008-04-14 16:18:06.000000', NULL, 1),
(4638959, 666585, 5364, '<td valign="top">Did you consider getting down to the same level as the dog, instead of looking down at it? It''s a technique that can give more interesting images.</td>', 'Did you consider getting down to the same level as the dog, instead of looking down at it? It''s a technique that can give more interesting images.', '2008-04-14 16:18:39.000000', NULL, 1),
