(4641900, 667096, 75651, '<td valign="top">Wonderful texture and color as well as sharpness. Very nice.</td>', 'Wonderful texture and color as well as sharpness. Very nice.', '2008-04-16 00:11:13.000000', NULL, 1),
(4641903, 666936, 75651, '<td valign="top">I LOVE old cameras.  Very nicely done with the sharpness colors and composition.</td>', 'I LOVE old cameras.  Very nicely done with the sharpness colors and composition.', '2008-04-16 00:11:50.000000', NULL, 1),
(4641904, 665989, 75651, '<td valign="top">Beautiful- Certainly a top ten for me!!</td>', 'Beautiful- Certainly a top ten for me!!', '2008-04-16 00:12:04.000000', NULL, 1),
(4641905, 667230, 75651, '<td valign="top">Awesome.  Great and daring photo.  Wonderful cropping- up nice tight and no where to run!!!  Beautifully done.</td>', 'Awesome.  Great and daring photo.  Wonderful cropping- up nice tight and no where to run!!!  Beautifully done.', '2008-04-16 00:12:38.000000', NULL, 1),
