(4641908, 667145, 75651, '<td valign="top">Beautiful flower- seems a bit blown out with the saturation though.</td>', 'Beautiful flower- seems a bit blown out with the saturation though.', '2008-04-16 00:13:41.000000', NULL, 1),
(4641911, 667122, 75651, '<td valign="top">Wondeful splash. Can''t give you credit for orginality but certainly well executed.  Nicely done.</td>', 'Wondeful splash. Can''t give you credit for orginality but certainly well executed.  Nicely done.', '2008-04-16 00:14:39.000000', NULL, 1),
(4641912, 666048, 75651, '<td valign="top">Very ncie old style photograph. very sharp with nice lines.</td>', 'Very ncie old style photograph. very sharp with nice lines.', '2008-04-16 00:15:03.000000', NULL, 1),
(4641914, 665712, 75651, '<td valign="top">Beautiful shot with some very nice lines.</td>', 'Beautiful shot with some very nice lines.', '2008-04-16 00:15:21.000000', NULL, 1),
(4641916, 667071, 75651, '<td valign="top">Very Very good IDEA- but the execution in my opinion is not there.  One more second when they burst out of the water is really the money shot.</td>', 'Very Very good IDEA- but the execution in my opinion is not there.  One more second when they burst out of the water is really the money shot.', '2008-04-16 00:16:15.000000', NULL, 1),
(4641917, 667134, 75651, '<td valign="top">Very concealed.  Nice colors and sharpness- don''t be afraid to crop in closer even in this centered challenge.</td>', 'Very concealed.  Nice colors and sharpness- don''t be afraid to crop in closer even in this centered challenge.', '2008-04-16 00:16:46.000000', NULL, 1),
