INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4641945, 666275, 75651, '<td valign="top">Awesome catch.  WOuld have really made a difference with that back wheel i the photo.</td>', 'Awesome catch.  WOuld have really made a difference with that back wheel i the photo.', '2008-04-16 00:23:47.000000', NULL, 1),
(4641946, 666094, 75651, '<td valign="top">Nice turtle and reflection. The horizon line throws me off- looks the turtle should be sliding off.</td>', 'Nice turtle and reflection. The horizon line throws me off- looks the turtle should be sliding off.', '2008-04-16 00:24:19.000000', NULL, 1),
(4641947, 667373, 75651, '<td valign="top">WAY too much frame- but nice flower.</td>', 'WAY too much frame- but nice flower.', '2008-04-16 00:24:42.000000', NULL, 1),
(4641949, 667146, 75651, '<td valign="top">Very nice job with a tough subject.  CLouds are tough and you pulled it off rather nicely.</td>', 'Very nice job with a tough subject.  CLouds are tough and you pulled it off rather nicely.', '2008-04-16 00:25:03.000000', NULL, 1),
(4641952, 667123, 75651, '<td valign="top">Absolutely perfect image and capture.  You''ve gotta submit that to a nature magazine- they would love it!</td>', 'Absolutely perfect image and capture.  You''ve gotta submit that to a nature magazine- they would love it!', '2008-04-16 00:25:30.000000', NULL, 1),
